    const c = cell.content
    if (c[0] === '=') {
      let ast = null
      try { ast = parseFormula(c.slice(1)) } catch { ast = null }
      v = ast ? ev(ast) : err('#ERR!')
      if (v.t === 'e' && v.v === '#CYCLE!') { /* keep */ }
