    const { name, args } = n
    const fns = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      if (args.some((a) => a.type === 'range')) return err('#ERR!')
