#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseSheet, evaluateAll, depsOf, show } from './sheet.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const sheet = parseSheet(readFileSync(0, 'utf8'))
if (sheet.error) {
  process.stderr.write(`error: ${sheet.error}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'values') {
  const get = evaluateAll(sheet.cells)
  for (const c of sheet.list) out += `${c.name}=${show(get(c))}\n`
} else {
  for (const c of sheet.list) out += `${c.name}:${depsOf(c.content).map((d) => ' ' + d).join('')}\n`
}
process.stdout.write(out)
