    if ('^*/+-=<>(),:'.includes(c)) { toks.push({ k: 'op', v: c }); i++; continue }
    throw new Error('syntax')
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const need = (v) => { if (!isOp(v)) throw new Error('syntax'); p++ }
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { type: 'neg', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Error('syntax')
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.k === 'op' && t.v === '(') { p++; const e = cmp(); need(')'); return { type: 'paren', e } }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (!isOp(')')) {
          args.push(cmp())
          while (isOp(',')) { p++; args.push(cmp()) }
        }
        need(')')
        return { type: 'call', name: t.v.toUpperCase(), args }
      }
      const u = t.v.toUpperCase()
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw new Error('syntax')
        p++
        return { type: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
      }
      if (u === 'TRUE') return { type: 'bool', v: true }
      if (u === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', a: parseAddr(t.v) }
    }
    throw new Error('syntax')
  }
  const e = cmp()
  if (p !== toks.length) throw new Error('syntax')
  return e
}

function cellsOfRange(r) {
  const out = []
  const c1 = Math.min(r.a.col, r.b.col), c2 = Math.max(r.a.col, r.b.col)
  const r1 = Math.min(r.a.row, r.b.row), r2 = Math.max(r.a.row, r.b.row)
  for (let c = c1; c <= c2; c++) for (let w = r1; w <= r2; w++) out.push({ col: c, row: w })
  return out
}

function collect(node, acc) {
  switch (node.type) {
    case 'ref': if (node.a) acc.push({ col: node.a.col, row: node.a.row }); break
    case 'range': if (node.a && node.b) acc.push(...cellsOfRange(node)); break
    case 'bin': collect(node.l, acc); collect(node.r, acc); break
    case 'neg': case 'paren': collect(node.e, acc); break
    case 'call': node.args.forEach((a) => collect(a, acc)); break
  }
}

export function depsOf(content) {
  if (content[0] !== '=') return []
  let ast
  try { ast = parseFormula(content.slice(1)) } catch { return [] }
  const acc = []
  collect(ast, acc)
  const seen = new Map()
  for (const c of acc) seen.set(c.col * 1000 + c.row, c)
  return [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((c) => nameOf(c.col, c.row))
}

// ---- evaluation ----
const toNum = (v) => (v.t === 'n' ? v : v.t === 'b' ? num(v.v ? 1 : 0) : v.t === 's' ? err('#VALUE!') : v)
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = (v) => (v.t === 'n' ? 0 : v.t === 's' ? 1 : 2)
function cpCmp(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (rank(a) !== rank(b)) return rank(a) - rank(b)
  if (a.t === 's') return cpCmp(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

export function evaluateAll(cells) {
  const memo = new Map()
  const busy = new Set()
  const asts = new Map()

  function cellValue(col, row) {
    const name = nameOf(col, row)
    const cell = cells.get(name)
    if (!cell) return num(0)
    if (memo.has(name)) return memo.get(name)
    if (busy.has(name)) return err('#CYCLE!')
    busy.add(name)
    let v
    const c = cell.content
    if (c[0] === '=') {
      let ast = null
      try { ast = parseFormula(c.slice(1)) } catch { ast = null }
      v = ast ? ev(ast) : err('#ERR!')
      if (v.t === 'e' && v.v === '#CYCLE!') { /* keep */ }
    } else if (c === '') v = num(0)
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) v = num(Number(c))
    else if (ERRS.includes(c)) v = err(c)
    else v = { t: 's', v: c }
    busy.delete(name)
    memo.set(name, v)
    return v
  }

  function ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'paren': return ev(n.e)
      case 'range': return err('#ERR!')
      case 'ref': return n.a ? cellValue(n.a.col, n.a.row) : err('#REF!')
      case 'neg': {
        const v = ev(n.e)
        if (v.t === 'e') return v
        const x = toNum(v)
        if (x.t === 'e') return x
        return n.op === '-' ? num(-x.v) : x
      }
      case 'bin': return binop(n)
      case 'call': return call(n)
    }
  }

  function binop(n) {
    const l = ev(n.l), r = ev(n.r)
    if (l.t === 'e') return l
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const d = compare(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return fin(a.v + b.v)
      case '-': return fin(a.v - b.v)
      case '*': return fin(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
      case '^': return fin(Math.pow(a.v, b.v))
    }
  }

  // expand arguments into values (errors included, in order)
  function expand(args) {
    const out = []
    for (const a of args) {
      if (a.type === 'range') {
        if (!a.a || !a.b) { out.push(err('#REF!')); continue }
        for (const c of cellsOfRange(a)) out.push(cellValue(c.col, c.row))
      } else out.push(ev(a))
    }
    return out
  }

  function call(n) {
    const { name, args } = n
    const fns = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      if (args.some((a) => a.type === 'range')) return err('#ERR!')
      const c = ev(args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? args[1] : args[2])
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const vs = expand(args)
      if (vs.length !== 1) return err('#ERR!')
      const x = toNum(vs[0])
      return x.t === 'e' ? x : num(Math.abs(x.v))
    }
    if (!fns.includes(name)) return err('#NAME?')
    if (args.length < 1) return err('#ERR!')
    const vs = expand(args)
    const e = vs.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vs.filter((v) => v.t === 'n').length)
    const ns = []
    for (const v of vs) {
      const x = toNum(v)
      if (x.t === 'e') return x
      ns.push(x.v)
    }
    if (name === 'SUM') return fin(ns.reduce((s, x) => s + x, 0))
    if (name === 'AVG') return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
    if (name === 'MIN') return fin(Math.min(...ns))
    return fin(Math.max(...ns))
  }

  return (c) => cellValue(c.col, c.row)
}

export function show(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return String(v.v)
}
